prog='''from collections import deque,Counter
def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    others={v for v in cnt if v!=bg}
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg or seen[r][c]: continue
            q=deque([(r,c)]); seen[r][c]=True; cells=[]; edge_sides=0; ok=True
            while q:
                rr,cc=q.popleft(); cells.append((rr,cc))
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if not (0<=nr<h and 0<=nc<w):
                        continue
                    if g[nr][nc]==bg:
                        if not seen[nr][nc]: seen[nr][nc]=True; q.append((nr,nc))
                    elif g[nr][nc] not in others:
                        ok=False
            # count edge sides of bounding exposure
            for rr,cc in cells:
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if not (0<=nr<h and 0<=nc<w): edge_sides+=1
            if ok and edge_sides<=1:
                for rr,cc in cells: out[rr][cc]=4
    return out
'''
