    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==line and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==line and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
